          {toast}
        </span>
        {toast && toastActions.length ? (
          <span className="toast-actions">
            {toastActions.map((a) => (
              <button
                key={a.label}
                type="button"
                onClick={() => {
                  setToast("");
                  setToastHeld(false);
                  a.run();
                  setFocusHeading((n) => n + 1);
                }}
              >
                {a.label}
              </button>
            ))}
          </span>
        ) : null}
      </div>
      {signingIn ? (
        <SignInDialog
          name={state.name}
          onClose={() => setSigningIn(false)}
          onSignIn={(name) => {
            update((s) => ({ ...s, name, signedIn: true }));
            setSigningIn(false);
            notify(
              `Signed in as ${name}. Demo only; nothing leaves this browser.`,
            );
          }}
        />
      ) : null}
      {rsvpEvent ? (
        <RsvpDialog
          key={rsvpEvent}
          event={EVENTS.find((e) => e.id === rsvpEvent)!}
          name={state.name}
          busy={enrolling}
          onClose={enrollment.cancel}
          onSubmit={(rsvp) => completeEnrollment(rsvpEvent, rsvp)}
        />
      ) : null}
      {detailEvent ? (
        <EventDetails
          event={detailEvent}
          state={state}
          onClose={closeDetail}
          onCommunity={(id) => nav("forum", id)}
          onAdd={add}
          onRemove={remove}
          onSave={save}
        />
      ) : null}
    </>
  );
}

