        );
      }
    }
    return {
      constraints: result.constraints,
      ids: result.event_ids,
      evidence: (result.recommendations || []).filter(
        (e) =>
          result.event_ids.includes(e.event_id) &&
          [e.interest_match, e.schedule_fit, e.practical, e.trade_offs].every(
            (v) => typeof v === "string",
