              .filter((e) => e.day === i && state.plan.includes(e.id))
              .map((e) => ({ ...e, kind: "event" })),
          ].sort((a, b) => a.start - b.start);
          return (
            <div className="week-day" key={day}>
              <div className={`day-head ${i === today ? "today" : ""}`}>
