            <label htmlFor="pe-location">Location (optional)</label>
            <input
              id="pe-location"
              type="text"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              maxLength={80}
              placeholder="Room, building, or link"
            />
          </div>

