            <label htmlFor="pe-calendar">Calendar</label>
            <select
              id="pe-calendar"
              value={calendar}
              onChange={(e) =>
                setCalendar(e.target.value as "personal" | "class")
              }
              disabled={block !== null}
            >
              <option value="personal">Personal</option>
              <option value="class">Class / busy time</option>
            </select>
          </div>

