            <p className="pe-field-error">
              Class / busy time only works on Mon–Fri.
            </p>
          )}
          {calendarClass && !isWeekend && repeat !== "weekly" && (
            <p className="pe-field-error">
              Class / busy time must be set to weekly.
            </p>
          )}

