                    type="button"
                    className="btn danger small"
                    onClick={handleDelete}
                  >
                    Delete
                  </button>
                  <button
                    type="button"
                    className="btn small"
                    onClick={() => setConfirmDelete(false)}
                  >
                    Cancel
                  </button>
                </div>
              ) : (
                <button
                  type="button"
                  className="btn danger small pe-delete-btn"
                  onClick={handleDelete}
                >
                  Delete
                </button>
              )
            ) : null}
            <div className="pe-dialog-actions-right">
