                Cancel
              </button>
              <button
                type="submit"
                className="btn primary small"
                disabled={submitDisabled}
              >
                {isEdit ? "Save" : "Create"}
              </button>
            </div>
          </div>
        </form>
      </dialog>
    </>
  );
}

