  | {
      kind: "event";
      id: string;
      title: string;
      day: number;
      start: number;
      end: number;
      cancelled: boolean;
      /** A time_moved update changed this event's start or end. */
      moved: boolean;
    }
  | {
      kind: "personal";
      id: string;
      title: string;
      day: number;
      start: number;
      end: number;
      location?: string;
      /** True for weekly-repeating items */
      weekly: boolean;
    };

