        month: "short",
        day: "numeric",
        timeZone: "UTC",
      }).format(dMon);
      const sunStr = new Intl.DateTimeFormat("en-US", {
        month: sameMonth ? undefined : "short",
        day: "numeric",
        year: sameYear ? undefined : "numeric",
