        return d === 0 ? 6 : d - 1;
      })();
      onThisDate = peWd === wd;
    }
    if (onThisDate) {
      items.push({
        kind: "personal",
        id: pe.id,
        title: pe.title,
        day: wd,
        start: pe.start,
        end: pe.end,
        location: pe.location,
        weekly: pe.repeat === "weekly",
      });
    }
  }
  const dayIdx = demoDayIndex(iso);
  if (dayIdx >= 0) {
    for (const e of events) {
      if (e.day !== dayIdx || !state.plan.includes(e.id)) continue;
      const o = original.find((x) => x.id === e.id);
      items.push({
        kind: "event",
        id: e.id,
        title: e.title,
        day: e.day,
        start: e.start,
        end: e.end,
