      /^\d{4}-\d{2}-\d{2}$/.test(anchor) &&
      noonUTCToIsoSafe(anchor) === anchor &&
      Math.abs(+anchor.slice(0, 4) - +fallbackAnchor.slice(0, 4)) <= 50;
