export function pixelToMins(
  pixelY: number,
  gridH: number,
  gridStart: number,
  gridEnd: number,
): number {
  const totalMin = (gridEnd - gridStart) * 60;
  const raw = (pixelY / gridH) * totalMin + gridStart * 60;
  return Math.round(raw / 15) * 15;
