export function clampStart(
  start: number,
  duration: number,
  gridStart: number,
  gridEnd: number,
  minDuration = 15,
): number {
  const dur = Math.max(duration, minDuration);
  const lo = gridStart * 60;
  const hi = gridEnd * 60 - dur;
  return Math.max(lo, Math.min(hi, start));
}

