 * Clamp an end time so it is at least `minDuration` minutes after `start`
 * and does not exceed `gridEnd`.
 */
export function clampEnd(
  end: number,
  start: number,
  gridEnd: number,
  minDuration = 15,
): number {
  return Math.min(gridEnd * 60, Math.max(start + minDuration, end));
}

