  items: T[],
): Array<{ item: T; col: number; totalCols: number }> {
  if (items.length === 0) return [];

  // Sort by start, then by duration desc
  const sorted = [...items].sort(
    (a, b) => a.start - b.start || b.end - b.start - (a.end - a.start),
