466 |   const focusMonth = monthStart(anchor);
467 |   const focusRef = useRef<HTMLDivElement>(null);
468 |   // Phones only: the year is one long column there, so bring the current
469 |   // month into view. On wider screens the 4×3 grid needs no scrolling, and
470 |   // scrollIntoView would also scroll the window and hide the toolbar.
471 |   useEffect(() => {
472 |     if (!window.matchMedia?.(PHONE_QUERY).matches) return;
473 |     focusRef.current?.scrollIntoView?.({ block: "nearest" });
474 |   }, [focusMonth]);
475 |   return (
476 |     <div className="gcal-year">
477 |       {months.map((m) => (
478 |         <MiniMonth
479 |           key={m}
480 |           monthIso={m}
481 |           state={state}
482 |           today={today}
483 |           onDayClick={onDayClick}
484 |           monthRef={m === focusMonth ? focusRef : undefined}
485 |         />
486 |       ))}
487 |     </div>
488 |   );
489 | }
