491 | // ── Main component ─────────────────────────────────────────────────────────
492 | 
493 | export function CalendarView({ state, onDetail, onDay, onEditAvailability, onExportCalendar }: CalendarViewProps) {
494 |   const zone = isTimeZone(state.timezone) ? state.timezone : DEMO.time_zone;
495 |   const today = todayIso(zone);
496 |   const home = today ?? DEMO.week_start;
497 | 
498 |   const [position, setPosition] = useState(() => parseSavedPosition(readSavedPosition(), home));
499 |   const { view, anchor } = position;
500 |   useEffect(() => writeSavedPosition(position), [position]);
501 |   const setView = (v: CalView) => setPosition((p) => ({ ...p, view: v }));
502 |   const setAnchor = (a: string) => setPosition((p) => ({ ...p, anchor: a }));
503 | 
504 |   const events = useMemo(() => effectiveEvents(state.appliedUpdateIds ?? []), [state.appliedUpdateIds]);
505 |   // Size the grid from the whole catalog plus busy times, so it never clips
506 |   // an item and keeps the same height in every week.
507 |   const allBlocks = useMemo(() => busyBlocks(state), [state]);
508 |   const grid = useMemo(() => gridHours([...events, ...allBlocks]), [events, allBlocks]);
509 |   const statuses = useStatuses(state, events);
510 |   // Show the amber legend key only when something on the plan needs attention.
511 |   const anyAttention = [...statuses].some(([id, s]) => s.tag && !state.cancelled.includes(id));
512 | 
513 |   const demoWeek = weekDates();
514 |   const showingDemoWeek =
515 |     view === "day"
516 |       ? demoWeek.includes(anchor)
517 |       : view === "week"
518 |         ? demoWeek.some((d) => weekDatesFor(anchor).includes(d))
519 |         : view === "month"
520 |           ? demoWeek.some((d) => sameMonth(d, anchor))
521 |           : demoWeek.some((d) => d.startsWith(anchor.slice(0, 4)));
522 | 
523 |   const goToDemoWeek = () => setPosition({ view: "week", anchor: home });
524 |   const openDay = (iso: string) => setPosition({ view: "day", anchor: iso });
525 | 
526 |   const viewDates = view === "day" ? [anchor] : view === "week" ? weekDatesFor(anchor) : [];
527 |   const unit = view === "day" ? "day" : view === "week" ? "week" : view === "month" ? "month" : "year";
528 |   const timeGridView = view === "day" || view === "week";
529 | 
