531 |     <div className="gcal-root">
532 |       <div className="gcal-toolbar">
533 |         <div className="gcal-toolbar-left">
534 |           <button className="btn small gcal-today-btn" onClick={() => setAnchor(home)} aria-label="Go to today">
535 |             Today
536 |           </button>
537 |           <button className="gcal-nav-btn" onClick={() => setAnchor(navigate(anchor, view, -1))} aria-label={`Previous ${unit}`}>
538 |             ‹
539 |           </button>
540 |           <button className="gcal-nav-btn" onClick={() => setAnchor(navigate(anchor, view, 1))} aria-label={`Next ${unit}`}>
541 |             ›
542 |           </button>
543 |           <span className="gcal-title">{viewTitle(anchor, view)}</span>
544 |         </div>
545 | 
546 |         <div className="gcal-toolbar-right">
547 |           <div className="gcal-toolbar-right-top">
548 |             <div className="gcal-view-switcher" role="group" aria-label="Calendar view">
549 |               {(["Day", "Week", "Month", "Year"] as const).map((v) => {
550 |                 const val = v.toLowerCase() as CalView;
551 |                 return (
552 |                   <button key={v} className={`gcal-switch-btn ${view === val ? "active" : ""}`} aria-pressed={view === val} onClick={() => setView(val)}>
553 |                     {v}
554 |                   </button>
555 |                 );
556 |               })}
557 |             </div>
558 |           </div>
559 |           <div className="gcal-toolbar-right-bottom">
560 |             <button className="text-btn" onClick={onEditAvailability} aria-label="Edit availability">
561 |               Edit availability <Icon name="arrow" />
562 |             </button>
563 |             <button className="btn small" onClick={onExportCalendar}>
564 |               <Icon name="download" />
565 |               Export calendar
566 |             </button>
567 |           </div>
