575 |             Busy commitments
576 |           </span>
577 |         ) : null}
578 |         <span>
579 |           <i className="dot green" />
580 |           Chosen events
581 |         </span>
582 |         {anyAttention ? (
583 |           <span>
584 |             <i className="dot amber" />
585 |             Needs attention
586 |           </span>
587 |         ) : null}
588 |         {!timeGridView ? <span>Classes appear in Day and Week view.</span> : null}
589 |         <span>
590 |           Times in campus time ({DEMO.time_zone}) · {state.buffer}-minute travel buffer
591 |         </span>
592 |       </div>
593 | 
594 |       {!showingDemoWeek && timeGridView ? <DemoWeekBanner onGoToDemo={goToDemoWeek} /> : null}
595 | 
596 |       {timeGridView ? (
597 |         <div className="gcal-body panel">
598 |           <TimeGrid
599 |             dates={viewDates}
600 |             state={state}
601 |             events={events}
602 |             grid={grid}
603 |             today={today}
604 |             statuses={statuses}
605 |             onDetail={onDetail}
606 |             onDay={onDay}
607 |           />
608 |         </div>
609 |       ) : null}
610 | 
611 |       {view === "month" ? (
612 |         <div className="gcal-body panel">
613 |           {!showingDemoWeek ? <DemoWeekBanner onGoToDemo={goToDemoWeek} /> : null}
614 |           <MonthView
615 |             anchor={monthStart(anchor)}
616 |             state={state}
617 |             events={events}
618 |             today={today}
619 |             statuses={statuses}
620 |             onDayClick={openDay}
621 |             onDetail={onDetail}
622 |           />
623 |         </div>
624 |       ) : null}
