626 |       {view === "year" ? (
627 |         <div className="gcal-body panel">
628 |           {!showingDemoWeek ? <DemoWeekBanner onGoToDemo={goToDemoWeek} /> : null}
629 |           <YearView anchor={anchor} state={state} today={today} onDayClick={openDay} />
630 |         </div>
631 |       ) : null}
