+
+  // ── Save handler ──────────────────────────────────────────────────────────
+  function handleSave(payload: PersonalEventSavePayload) {
+    if (payload.block) {
+      const b = payload.block;
+      onUpdate((s) => {
+        const existing = s.blocks.find((x) => x.id === b.id);
+        if (existing) {
+          return { ...s, blocks: s.blocks.map((x) => (x.id === b.id ? b : x)) };
