                      onChange={(e) => setMessage(e.target.value)}
                      onKeyDown={(e) => {
                        if (
                          e.key === "Enter" &&
                          !e.shiftKey &&
                          !e.nativeEvent.isComposing
                        ) {
                          e.preventDefault();
                          void chat(message);
                        }
                      }}
                    />
                    <button
                      aria-label="Send message"
                      disabled={busy || !message.trim()}
                    >
                      <Icon name="send" />
                    </button>
                  </form>
                  <p className="fineprint">{chatFineprint}</p>
                </section>
                {calendarOpen ? (
                  <PlannerCalendar
                    state={state}
                    onClose={() => setCalendarOpen(false)}
                    onDetails={setDetail}
                  />
                ) : (
                  <aside className="stack">
                    <section className="panel">
                      <div className="section-bar">
                        <h2>Your draft plan</h2>
                        <span className="tag">
                          {draft.length} {draft.length === 1 ? "idea" : "ideas"}
                        </span>
                      </div>
                      {draft.length ? (
                        draft.map((e) => (
                          <div className="draft-item" key={e!.id}>
                            <span className="tag">{e!.category}</span>
                            <button
                              className="event-title"
                              onClick={() => setDetail(e!.id)}
                            >
                              <h3>{e!.title}</h3>
                            </button>
                            <div className="meta">
                              <Icon name="clock" />
                              {when(e!)}
                            </div>
                            <div className="reason">
                              {reasons(e!, state, state.constraints).map(
                                (r) => (
                                  <div key={r}>• {r}</div>
                                ),
                              )}
                            </div>
                            <Button
                              className="small"
                              onClick={() => add(e!.id)}
                            >
                              <Icon name="plus" />
                              Add to my calendar
                            </Button>
                          </div>
                        ))
                      ) : (
                        <Empty title="A little space for possibility">
                          Start a conversation to see a few events selected for
                          you.
                        </Empty>
                      )}
                      <p className="fineprint">
                        You choose what makes it into your week.
                      </p>
                    </section>
                    {state.plan.some((id) => !state.cancelled.includes(id)) ? (
                      <section className="panel">
                        <h2>Try a change of plans</h2>
                        <p className="sub">
                          Simulate a cancellation, then find an alternative that
                          fits.
                        </p>
                        <Button
                          className="small"
                          onClick={() => {
                            const id = demo
                              .read()
                              .plan.find(
                                (id) => !demo.read().cancelled.includes(id),
                              );
                            if (id)
                              update((s) => ({
                                ...s,
                                cancelled: [...s.cancelled, id],
                              }));
                            notify(
                              "Demo cancellation created. Your other events are unchanged.",
                            );
                          }}
                        >
                          Simulate event cancellation
                        </Button>
                      </section>
                    ) : null}
                  </aside>
                )}
              </div>
            </>
          ) : null}
          {page === "calendar" ? (
            <>
              <button
                className="text-btn sub-page-back"
                onClick={closeCalendar}
              >
                <span className="flip">
                  <Icon name="arrow" />
                </span>
                Back to {labels[calendarFrom]}
              </button>
              <Heading
                title="Make room for what matters."
                description="Your classes, your plans, and a little breathing room."
                timezone={state.timezone}
              />

              {cancelled ? (
                <div className="notice">
                  A planned event is now unavailable — cancelled, full, or moved
                  into a conflict.{" "}
                  <Button className="small" onClick={replan} disabled={busy}>
                    Find a replacement
                  </Button>
                </div>
              ) : null}

              <CalendarView
                state={state}
                onDetail={setDetail}
                onDay={findOnDay}
                onEditAvailability={() => nav("profile")}
                onExportCalendar={exportCalendar}
                onUpdate={update}
                notify={notify}
              />

              <section style={{ marginTop: 28 }}>
                <div className="section-bar">
                  <h2>Your campus plans</h2>
                  <button className="text-btn" onClick={() => nav("planner")}>
                    Find my next event <Icon name="arrow" />
                  </button>
                </div>
                {state.plan.length ? (
                  effEvents
                    .filter((e) => state.plan.includes(e.id))
                    .map((e) => (
                      <div className="block-row" key={e.id}>
                        <div>
                          <strong>
                            {e.title}
                            {state.cancelled.includes(e.id)
                              ? " · Cancelled"
                              : ""}
                          </strong>
                          <small>
                            {when(e)} · {e.location}
                            {(() => {
                              const o = EVENTS.find((x) => x.id === e.id);
                              return o &&
                                (o.start !== e.start || o.end !== e.end)
                                ? " · Time changed"
                                : "";
                            })()}
                          </small>
                        </div>
                        <Button className="small" onClick={() => remove(e.id)}>
                          Remove
                        </Button>
                      </div>
                    ))
                ) : (
                  <Empty title="Your week is waiting">
                    Choose an event or ask the planner to help you get started.
                    <p>
                      <Button
                        className="primary"
                        onClick={() => nav("planner")}
                      >
                        Plan with me
                      </Button>
                    </p>
                  </Empty>
                )}
              </section>
            </>
          ) : null}
          {page === "profile" ? (
            <Profile
              state={state}
              update={update}
              notify={notify}
              watsonxMode={watsonxMode}
            />
          ) : null}
          {page === "forum" ? (
            <Forum
              state={state}
              update={update}
              notify={notify}
              selected={selectedCommunity}
              onSelect={(id) => (id ? nav("forum", id) : closeCommunity())}
            />
          ) : null}
          {page === "settings" ? (
            <Settings
              state={state}
              update={update}
              notify={notify}
              watsonxMode={watsonxMode}
              sidebarCollapsed={collapsed}
              onSidebarCollapsed={setCollapsed}
              unreadCount={unreadNotes.length}
              updatesWaiting={updatesWaiting}
              onProfile={() => nav("profile")}
              onSignIn={() => setSigningIn(true)}
              onReview={() => nav("review")}
              onNotifications={() => openNotifications()}
              onMarkAllRead={() => {
                markRead(unreadNotes.map((n) => n.id));
                notify("All notifications marked as read.");
              }}
              onCheckUpdates={checkForUpdates}
              onExport={exportCalendar}
              onPlanner={() => nav("planner")}
              onReset={() => {
                conversation.reset();
                enrollment.reset();
                setCalendarOpen(false);
                update(fresh);
                nav("home");
                notify("Demo restored. You’re ready to present.");
              }}
            />
          ) : null}
          <footer className="section-footer">
            <span>
              Campus Compass · IBM AI Experiential Learning Lab project
            </span>
            <span>
              Fictional data · Demo week, {WEEK_LABEL} · {DEMO.time_zone}
            </span>
          </footer>
        </main>
      </div>
      <div
        id="toast"
        className={toast ? "show" : ""}
        onMouseEnter={() => setToastHeld(true)}
        onMouseLeave={() => setToastHeld(false)}
        onFocus={() => setToastHeld(true)}
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget)) setToastHeld(false);
        }}
      >
        {/* Only the message is announced; the actions are ordinary buttons. */}
        <span role="status" aria-live="polite">
          {toast}
        </span>
        {toast && toastActions.length ? (
          <span className="toast-actions">
            {toastActions.map((a) => (
              <button
                key={a.label}
                type="button"
                onClick={() => {
                  setToast("");
                  setToastHeld(false);
                  a.run();
                  setFocusHeading((n) => n + 1);
                }}
              >
                {a.label}
              </button>
            ))}
          </span>
        ) : null}
      </div>
      {signingIn ? (
        <SignInDialog
          name={state.name}
          onClose={() => setSigningIn(false)}
          onSignIn={(name) => {
            update((s) => ({ ...s, name, signedIn: true }));
            setSigningIn(false);
            notify(
              `Signed in as ${name}. Demo only; nothing leaves this browser.`,
            );
          }}
        />
      ) : null}
      {rsvpEvent ? (
        <RsvpDialog
          key={rsvpEvent}
          event={EVENTS.find((e) => e.id === rsvpEvent)!}
          name={state.name}
          busy={enrolling}
          onClose={enrollment.cancel}
          onSubmit={(rsvp) => completeEnrollment(rsvpEvent, rsvp)}
        />
      ) : null}
      {detailEvent ? (
        <EventDetails
          event={detailEvent}
          state={state}
          onClose={closeDetail}
          onCommunity={(id) => nav("forum", id)}
          onAdd={add}
          onRemove={remove}
          onSave={save}
          onDetail={setDetail}
        />
      ) : null}
    </>
  );
}

