  display: flex;
  flex-direction: column;
  flex: 1;
}
.tag {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: #527654;
  font-weight: 700;
  display: inline-block;
  margin-bottom: 8px;
}
.tag.career {
  color: #795c94;
}
.tag.social {
  color: #936b36;
}
.event-title {
  background: none;
  border: 0;
  text-align: left;
  padding: 0;
  margin-bottom: 11px;
}
.event-title:hover {
  color: var(--green);
}
.event-title h3 {
  font-size: 14px;
  min-height: 35px;
}
.meta {
  color: var(--muted);
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-size: 11px;
  margin: 5px 0;
  line-height: 1.5;
}
.meta .icon {
  width: 13px;
  height: 13px;
  margin-top: 1px;
}
.reason {
  font-size: 11px;
  line-height: 1.6;
  color: #527357;
  padding-top: 10px;
  margin-top: auto;
  margin-bottom: 11px;
}
.reason.blocked {
  color: var(--notice-ink);
}
.event-body .btn.blocked {
  background: var(--notice-bg);
  border-color: #ead9b4;
  color: var(--notice-ink);
}
.event-body .btn.blocked:hover {
  background: #f3e6c9;
}
.event-body .btn {
  width: 100%;
  font-size: 11px;
  padding: 7px;
  min-height: 32px;
}
.rail .panel {
  padding: 20px;
}
.rail h2 {
  font-size: 15px;
}
.planner-teaser {
  text-align: center;
  background: #fff;
}
.mascot {
  width: 125px;
  height: 120px;
  object-fit: contain;
  display: block;
  margin: 0 auto 12px;
}
.planner-teaser h2 {
  font-size: 20px;
}
.planner-teaser p {
  font-size: 12px;
  color: var(--muted);
  margin: 9px 0 16px;
}
.planner-teaser .btn {
  width: 100%;
}
.label {
  font-size: 10px;
  letter-spacing: 0.5px;
  color: var(--muted);
  display: inline-block;
  margin-top: 12px;
}
.feed {
  border-bottom: 1px solid var(--line);
  padding: 13px 0;
}
.feed:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.feed strong {
  font-size: 12px;
  font-weight: 600;
  line-height: 1.5;
}
.feed p {
  font-size: 11px;
  color: var(--muted);
  margin: 4px 0 0;
}
.feed .text-btn {
  font-size: 11px;
  margin-top: 6px;
  padding-left: 0;
}
.group {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 10px 0;
}
.group-icon {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: #eff1e7;
  color: #6c7b52;
}
.group strong {
  font-size: 12px;
}
.group small {
  display: block;
  font-size: 10px;
  color: var(--muted);
  margin-top: 3px;
}
.section-footer {
  font-size: 11px;
  color: var(--muted);
  margin-top: 25px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.planner-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 22px;
}
.chat-panel {
  display: flex;
  flex-direction: column;
  min-height: 620px;
}
.chat-header {
  display: flex;
  gap: 12px;
  align-items: center;
  padding-bottom: 17px;
  border-bottom: 1px solid var(--line);
}
.chat-header img {
  width: 45px;
  height: 45px;
  object-fit: contain;
}
.chat-header h2 {
  font-size: 16px;
}
.status-label {
  font-size: 11px;
  color: var(--muted);
  margin-top: 4px;
  display: block;
}
.messages {
  flex: 1;
  min-height: 310px;
  max-height: 570px;
  overflow: auto;
  padding: 20px 0;
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.message {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.message img {
  width: 30px;
  height: 32px;
  object-fit: contain;
}
.bubble {
  background: var(--bg);
  border-radius: 0 12px 12px 12px;
  padding: 14px 16px;
  font-size: 13px;
  line-height: 1.7;
  max-width: 90%;
  white-space: pre-line;
}
.message.user-msg {
  justify-content: flex-end;
}
.user-msg .bubble {
  background: var(--mint);
  border-radius: 12px 0 12px 12px;
  color: var(--green-dark);
}
.prompts {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 15px;
}
.prompts button {
  font-size: 11px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 8px 10px;
  text-align: left;
}
.prompts button:hover {
  border-color: var(--green);
  background: var(--mint);
}
.active-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
  padding: 8px 10px;
  background: var(--mint);
  border-radius: 8px;
  border: 1px solid #bacdbc;
}
.active-filters-label {
  font-size: 10px;
  color: var(--muted);
  font-weight: 600;
  white-space: nowrap;
}
.filter-chip {
  font-size: 10px;
  background: white;
  border: 1px solid var(--green);
  border-radius: 12px;
  padding: 4px 10px;
  color: var(--green);
  cursor: pointer;
  font-weight: 500;
  transition: background 0.1s;
}
.filter-chip:hover:not(:disabled) {
  background: var(--green);
  color: white;
}
.filter-chip:disabled {
  opacity: 0.55;
  cursor: default;
}
.filter-chip-clear {
  border-color: var(--muted);
  color: var(--muted);
  margin-left: auto;
}
.filter-chip-clear:hover:not(:disabled) {
  background: var(--muted);
  color: white;
}
.example-prompts {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 10px;
}
.example-prompt-btn {
  font-size: 11px;
  background: var(--mint);
  border: 1px solid var(--green);
  border-radius: 8px;
  padding: 8px 12px;
  text-align: left;
  color: var(--green);
  cursor: pointer;
  font-weight: 500;
}
.example-prompt-btn:hover:not(:disabled) {
  background: var(--green);
  color: white;
}
.example-prompt-btn:disabled {
  opacity: 0.55;
  cursor: default;
}
.overlap-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--muted);
  margin: 12px 0 6px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.composer {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  border: 1px solid #bacdbc;
  border-radius: 10px;
  padding: 9px 10px;
  background: white;
}
.composer textarea {
  border: 0;
  resize: none;
  flex: 1;
  min-width: 0;
  padding: 5px;
  font-size: 13px;
  line-height: 1.5;
  outline: none;
  height: 46px;
  max-height: 130px;
}
.composer button {
  background: var(--green);
  color: white;
  border: 0;
  border-radius: 7px;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
}
.fineprint {
  font-size: 10px;
  line-height: 1.5;
  color: var(--muted);
  margin: 9px 0 0;
  text-align: center;
}
.draft-item {
  padding: 15px 0;
  border-bottom: 1px solid var(--line);
}
.draft-item:last-child {
  border: 0;
}
.draft-item h3 {
  font-size: 13px;
}
.draft-item .meta {
  font-size: 11px;
}
.draft-item .reason {
  margin-bottom: 8px;
}
.draft-item .btn {
  width: 100%;
}
.empty {
  text-align: center;
  padding: 40px 20px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
}
.empty .icon {
  display: block;
  margin: 0 auto 15px;
  width: 30px;
  height: 30px;
  color: #9fb39e;
}
.empty h3 {
  color: var(--ink);
  margin-bottom: 8px;
}
.summary-line {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  font-size: 12px;
  border-bottom: 1px solid var(--line);
}
.summary-line:last-child {
  border: 0;
}
.notice {
  border-radius: 9px;
  background: var(--notice-bg);
  color: var(--notice-ink);
  padding: 13px 15px;
  font-size: 12px;
  line-height: 1.6;
  margin-bottom: 18px;
}
.notice .btn {
  margin-top: 9px;
}
.calendar-full .week {
  gap: 13px;
}
.calendar-full .calendar-item {
  font-size: 13px;
  min-height: 90px;
  padding: 15px;
}
.calendar-full .calendar-item strong {
  font-size: 13px;
}
.calendar-full .calendar-item span {
  font-size: 12px;
}
.calendar-full .week-day {
  min-height: 330px;
}
.calendar-full .day-head {
  padding-bottom: 20px;
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 13px;
  color: var(--muted);
}
.field input,
.field select,
.field textarea {
  border: 1px solid var(--line);
  border-radius: 7px;
  background: white;
  padding: 11px;
  color: var(--ink);
  width: 100%;
}
.field textarea {
  min-height: 90px;
}
.field.full {
  grid-column: 1/-1;
}
.row {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.block-row {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid var(--line);
  font-size: 13px;
}
.block-row small {
  display: block;
  color: var(--muted);
  margin-top: 5px;
}
.wide-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 24px;
}
.topic-options {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 16px 0;
}
.topic-options label {
  font-size: 13px;
  background: var(--bg);
  padding: 10px;
  border-radius: 7px;
}
.topic-options input {
  accent-color: var(--green);
  margin-right: 7px;
}
.discussion {
  padding: 20px 0;
  border-bottom: 1px solid var(--line);
  display: flex;
  gap: 15px;
}
.discussion p {
  font-size: 13px;
  margin: 8px 0;
  color: var(--muted);
}
.discussion .avatar {
  flex: none;
}
.discussion small {
  color: var(--muted);
  font-size: 11px;
}
.discussion button {
  margin-top: 8px;
}
.settings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 0;
  border-bottom: 1px solid var(--line);
}
.settings-row p {
  margin: 5px 0 0;
  font-size: 13px;
  color: var(--muted);
}
.settings-row input {
  accent-color: var(--green);
  width: 18px;
  height: 18px;
}
.settings-row:last-child {
  border: 0;
}
.mobile-menu {
  display: none;
}
/* ── Event detail full-page overlay ─────────────────────────────────────── */
.event-detail-overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
}
.event-detail-backdrop {
  position: fixed;
  inset: 0;
  background: #15291f60;
  z-index: 199;
}
.event-detail-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 56px;
  background: white;
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  z-index: 201;
  box-shadow: 0 2px 8px #183e3108;
}
.event-detail-close {
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
}
.event-detail-close:hover {
  background: var(--bg);
}
.event-detail-scroll {
  position: fixed;
  inset: 56px 0 0 0;
  overflow-y: auto;
  z-index: 200;
  background: var(--bg);
}
/* Full-page content wrapper, max-width centred */
.event-detail-page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 0 32px;
}
/* ── Poster banner ── */
.ed-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  margin: 8px 24px 0;
  padding: 0;
  border: none;
  background: none;
  color: var(--green);
  font-size: 14px;
  font-weight: 600;
}
.ed-back:hover {
  color: var(--green-dark);
  text-decoration: underline;
}
.ed-back .icon {
  transform: rotate(180deg);
  width: 16px;
}
/* Design: a solid dark-green poster filling a light-green band. */
.ed-banner-wrap {
  background: #dfeadf;
  border-radius: 20px;
  padding: 0 clamp(0px, 8vw, 120px);
  margin: 8px 24px 0;
  overflow: hidden;
}
.ed-poster.poster {
  border-radius: 0;
  height: auto;
  min-height: 340px;
  padding: 44px 48px;
  background: var(--green);
  color: #e8f2e9;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
}
.ed-poster::after {
  display: none;
}
.ed-poster-left {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 10px;
  padding-right: 32px;
}
.ed-poster-topic {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.14em;
  opacity: 0.8;
}
/* Beats the shared `.poster b` card rule (21px, max-width 120px). */
.ed-poster .ed-poster-title {
  max-width: none;
  font-size: clamp(64px, 10vw, 120px);
  font-weight: 800;
  line-height: 0.9;
  letter-spacing: -2px;
  display: block;
}
.ed-poster-right {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 6px;
  min-width: 220px;
  text-align: right;
  border-top: 2px solid #e8f2e9;
  padding-top: 14px;
  font-size: 15px;
  font-weight: 600;
}
.ed-poster-rule {
  display: none;
}
.ed-poster-date {
  font-size: 22px;
  font-weight: 800;
}
.ed-poster-time {
  font-size: 15px;
  font-weight: 600;
}
.ed-poster-loc,
.ed-poster-host {
  font-size: 15px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 260px;
}
/* ── Follow / Contact / map / travel controls ── */
.ed-outline-btn,
.ed-fill-btn {
  min-height: 44px;
  padding: 0 20px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
}
.ed-outline-btn {
  border: 1px solid #cfd8cc;
  background: white;
  color: var(--green-dark);
}
.ed-outline-btn:hover {
  background: var(--bg);
}
.ed-outline-btn[aria-pressed="true"] {
  background: var(--mint);
  border-color: var(--green);
}
.ed-fill-btn {
  border: none;
  background: var(--green);
  color: white;
}
.ed-fill-btn:hover {
  background: var(--green-dark);
}
.ed-fill-btn[aria-pressed="true"] {
  background: var(--mint);
  color: var(--green-dark);
  box-shadow: inset 0 0 0 1px var(--green);
}
.ed-host-actions {
  display: flex;
  gap: 10px;
  margin-left: auto;
}
.ed-host-follow {
  margin-left: auto;
}
.ed-host-card > .ed-host-actions {
  flex: none;
  flex-direction: row;
  align-items: center;
}
.ed-demo-note {
  margin: 8px 0 0;
  font-size: 13px;
  color: #5b665f;
}
.ed-travel {
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-top: 1px solid var(--line);
  padding-top: 16px;
  margin-top: 8px;
}
.ed-travel h3 {
  margin: 0 0 4px;
  font-size: 16px;
}
.ed-travel-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding: 0;
  border: none;
  background: none;
  color: var(--green);
  font-size: 15px;
  font-weight: 600;
  text-align: left;
}
.ed-travel-btn:hover {
  text-decoration: underline;
}
.ed-travel-btn[aria-pressed="true"] {
  color: var(--green-dark);
  text-decoration: underline;
}
.ed-map-placeholder {
  flex-direction: column;
  gap: 8px;
}
/* ── Share / Save icon row ── */
.ed-icon-row {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 24px 4px;
}
.ed-icon-btn {
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ed-icon-btn:hover {
  background: var(--bg);
}
.ed-icon-btn.selected {
  background: var(--mint);
  border-color: var(--green);
  color: var(--green);
}
/* ── Two-column layout ── */
.event-detail-body {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px 24px 60px;
  display: flex;
  gap: 32px;
  align-items: flex-start;
}
.event-detail-main {
  flex: 999 1 560px;
  display: flex;
  flex-direction: column;
  min-width: 0;
}
/* ── Section layout ── */
.ed-section {
  padding: 32px 0;
  border-top: 1px solid var(--line);
}
.ed-section:first-child {
  border-top: none;
  padding-top: 16px;
}
.ed-section-heading {
  font-size: 26px;
  font-weight: 800;
  color: var(--green-dark);
  margin: 0 0 16px;
}
.ed-section-sub {
  font-size: 15px;
  color: #5b665f;
  margin: -8px 0 16px;
}
/* ── 1. Title block ── */
.ed-title-block {
  gap: 0;
}
.ed-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}
.ed-cat-pill {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 4px 10px;
  border-radius: 20px;
  background: var(--mint);
  color: var(--green);
}
.ed-demo-pill {
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  border: 1.5px dashed var(--line);
  color: var(--muted);
}
.ed-title {
  font-size: clamp(32px, 4vw, 46px);
  font-weight: 800;
  letter-spacing: -0.5px;
  line-height: 1.12;
  margin: 0 0 18px;
  color: var(--green-dark);
}
.ed-host-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}
.ed-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--green);
  color: white;
  font-size: 18px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  letter-spacing: 0.02em;
}
.ed-avatar--lg {
  width: 64px;
  height: 64px;
  font-size: 22px;
}
.ed-host-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 15px;
}
.ed-host-sub {
  font-size: 13px;
  color: #5b665f;
}
.ed-meta-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 15px;
  color: var(--ink);
  margin-bottom: 10px;
}
.ed-meta-row .icon {
  flex: none;
  margin-top: 2px;
  color: var(--muted);
}
.ed-meta-sub {
  color: #5b665f;
  font-size: 14px;
  margin-top: -4px;
}
.ed-badge-inline {
  margin-left: 8px;
  vertical-align: middle;
}
/* Update notice */
.ed-update-notice {
  margin-top: 12px;
  padding: 12px 16px;
  border-radius: 10px;
  font-size: 15px;
  line-height: 1.5;
}
.ed-update-notice--info {
  background: var(--info-bg);
  color: var(--info-ink);
  border: 1px solid #c9dcf1;
}
.ed-update-notice--info strong {
  color: #173d66;
}
.ed-struck {
  color: #4f6a87;
  text-decoration: line-through;
}
.ed-update-notice.notice--conflict {
  background: var(--notice-bg);
  color: var(--notice-ink);
  border: 1px solid #e2c98a;
  padding: 12px 16px;
  border-radius: 10px;
}
.ed-update-notice.notice--conflict p {
  margin: 6px 0 0;
  font-size: 14px;
}
/* ── 2. Overview ── */
.event-detail-desc {
  font-size: 17px;
  line-height: 1.6;
  color: var(--ink);
  max-width: 640px;
  margin: 0 0 16px;
}
.ed-goals-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 14px;
}
.ed-goals-label {
  font-weight: 600;
  color: #5b665f;
}
.ed-goal-pill {
  background: var(--mint);
  color: var(--green-dark);
  font-size: 13px;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 20px;
}
/* ── 3. Good to know ── */
.ed-cards-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.ed-card {
  background: white;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 20px;
}
.ed-card-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--green-dark);
  margin: 0 0 14px;
}
.ed-card-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 15px;
}
.ed-card-list li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  color: var(--ink);
}
.ed-card-list .icon {
  flex: none;
  margin-top: 2px;
  color: var(--muted);
}
.ed-conditions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 14px;
}
.ed-condition-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.ed-condition-label {
  color: #5b665f;
}
.ed-condition-value {
  display: flex;
  align-items: center;
  gap: 4px;
  font-weight: 600;
}
.ed-condition-value.confirmed {
  color: var(--green);
}
.ed-condition-value.confirmed .icon {
  color: var(--green);
}
.ed-condition-value.unconfirmed {
  color: var(--notice-ink);
}
.ed-condition-value.unconfirmed .icon {
  color: var(--notice-ink);
}
.ed-why-fits {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ed-why-label {
  font-size: 13px;
  font-weight: 700;
  color: #5b665f;
  margin-bottom: 4px;
  display: block;
}
.ed-why-item {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-size: 14px;
  color: var(--green-dark);
  font-weight: 500;
}
.ed-why-item .icon {
  flex: none;
  margin-top: 2px;
  color: var(--green);
}
/* ── 4. Location ── */
.ed-location-row {
  display: flex;
  gap: 20px;
  align-items: flex-start;
}
.ed-location-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 140px;
  font-size: 15px;
}
.ed-location-sub {
  font-size: 13px;
  color: #5b665f;
}
.ed-location-note {
  font-size: 13px;
  color: var(--muted);
  margin-top: 8px;
  font-style: italic;
}
.ed-map-placeholder {
  flex: 1;
  min-height: 300px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--muted);
  font-weight: 600;
  background-image: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 29px,
      var(--line) 29px,
      var(--line) 30px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 29px,
      var(--line) 29px,
      var(--line) 30px
    );
}
/* ── 5. Hosted by ── */
.ed-host-card {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 18px 20px;
  margin-bottom: 20px;
}
.ed-host-card > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 15px;
}
.ed-communities {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.ed-communities-label {
  font-size: 15px;
  font-weight: 700;
  color: var(--green-dark);
}
.event-detail-communities {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.event-detail-community-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--green);
  background: var(--mint);
  padding: 5px 12px;
  border-radius: 20px;
  text-decoration: none;
}
.event-detail-community-link:hover {
  background: #d4ebd6;
}
/* ── 6. Record & evidence ── */
.event-detail-evidence {
  background: white;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px 22px;
  font-size: 14px;
}
.event-detail-evidence summary {
  font-weight: 700;
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: space-between;
}
.event-detail-evidence summary::before {
  content: "▶";
  font-size: 11px;
  color: var(--muted);
  transition: transform 0.15s;
  flex: none;
}
.event-detail-evidence[open] summary::before {
  transform: rotate(90deg);
}
.ed-evidence-checked {
  font-size: 13px;
  font-weight: 400;
  color: var(--muted);
  margin-left: auto;
}
/* ── 7. You might also like ── */
.ed-related-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.ed-related-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
  background: none;
  border-left: none;
  border-right: none;
  border-top: none;
  border-radius: 0;
  text-align: left;
  width: 100%;
  cursor: pointer;
  transition: background 0.1s;
}
.ed-related-item:last-child {
  border-bottom: none;
}
.ed-related-item:hover {
  background: var(--mint);
}
.ed-related-poster.poster {
  width: 150px;
  height: 84px;
  border-radius: 10px;
  flex: none;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  padding: 8px 10px;
}
.ed-related-poster::after {
  display: none;
}
.ed-related-poster.poster b {
  max-width: none;
  font-size: 16px;
  font-weight: 800;
  line-height: 1;
}
.ed-related-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.ed-related-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--green-dark);
  line-height: 1.25;
}
.ed-related-when,
.ed-related-meta {
  font-size: 14px;
  color: #5b665f;
}
.ed-related-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}
/* ── Aside: RSVP card ── */
.event-detail-aside {
  flex: 0 0 clamp(300px, 25vw, 360px);
  align-self: stretch;
}
/* The aside stretches to the full column height; the card sticks inside it,
   relative to .event-detail-scroll (which already starts below the close bar). */
.ed-rsvp-card {
  position: sticky;
  top: 24px;
  background: white;
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.ed-rsvp-price {
  font-size: 17px;
  font-weight: 700;
  color: var(--ink);
  margin: 0;
}
.ed-rsvp-when {
  font-size: 15px;
  color: var(--muted);
  margin: 0;
}
.ed-issue-strip {
  background: var(--notice-bg);
  color: var(--notice-ink);
  border-radius: 8px;
  padding: 10px 14px;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
}
.ed-issue-strip strong {
  color: #6b4f1d;
}
.ed-issue-strip .icon {
  flex: none;
  margin-top: 1px;
  color: var(--notice-ink);
}
.ed-rsvp-btn {
  min-height: 52px;
  font-size: 16px;
}
.ed-rsvp-fine {
  text-align: center;
  margin: 0;
  font-size: 12px;
  color: var(--muted);
  line-height: 1.4;
}
/* Mobile bottom bar */
.ed-mobile-bar {
  display: none;
}
/* ── Mobile ≤ 700px ── */
@media (max-width: 700px) {
  .ed-banner-wrap {
    margin: 12px 12px 0;
    border-radius: 16px;
    padding: 12px;
  }
  .ed-poster.poster {
    min-height: auto;
    padding: 20px 20px 16px;
    flex-direction: column;
    gap: 12px;
  }
  .ed-poster .ed-poster-title {
    font-size: 54px;
  }
  .ed-poster-right {
    min-width: 0;
  }
  .ed-poster-loc,
  .ed-poster-host {
    display: none;
  }
  .ed-icon-row {
    padding: 10px 16px 4px;
  }
  .event-detail-body {
    flex-direction: column;
    padding: 12px 16px 160px;
    gap: 0;
  }
  .event-detail-aside {
    display: none;
  }
  .ed-cards-row {
    grid-template-columns: 1fr;
  }
  .ed-location-row {
    flex-direction: column;
  }
  .ed-map-placeholder {
    min-height: 180px;
    width: 100%;
  }
  .ed-related-poster.poster {
    width: 88px;
    height: 64px;
    padding: 6px 8px;
  }
  .ed-related-poster.poster b {
    font-size: 12px;
  }
  .ed-related-title {
    font-size: 15px;
  }
  /* Fixed bottom bar on mobile */
  .ed-mobile-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 8px 12px;
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 202;
    background: white;
    border-top: 1px solid var(--line);
    box-shadow: 0 -8px 24px #183e3112;
    padding: 12px 16px calc(24px + env(safe-area-inset-bottom));
  }
  .ed-mobile-bar-left {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 1;
    min-width: 0;
  }
  .ed-mobile-issue {
    font-size: 13px;
    color: var(--notice-ink);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .ed-mobile-fine {
    flex: 1 0 100%;
    margin: 0;
    font-size: 11px;
    color: #5b665f;
    text-align: center;
  }
}
#toast {
  position: fixed;
  bottom: 25px;
  left: calc(50% + 100px);
  transform: translateX(-50%) translateY(20px);
  opacity: 0;
  pointer-events: none;
  z-index: 100;
  background: var(--green-dark);
  color: white;
  border-radius: 9px;
  padding: 13px 22px;
  box-shadow: var(--shadow);
  font-size: 13px;
  transition:
    opacity 0.2s,
    transform 0.2s;
  max-width: calc(100% - 32px);
}
#toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
  pointer-events: auto;
}
#toast {
  display: flex;
  align-items: center;
  gap: 16px;
}
.toast-actions {
  display: flex;
  gap: 4px;
  flex: none;
}
.toast-actions button {
  background: transparent;
  border: 0;
  color: var(--mint);
  font: inherit;
  font-weight: 700;
  padding: 6px 8px;
  border-radius: 6px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.toast-actions button:hover {
  background: #ffffff1f;
}
.toast-actions button:focus-visible {
  outline: 2px solid var(--mint);
  outline-offset: 1px;
}
.page-enter {
  animation: reveal 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes reveal {
  from {
    opacity: 0.6;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@media (min-width: 1600px) {
