  color: var(--green-dark);
}
.event-detail-communities {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.event-detail-community-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--green);
  background: var(--mint);
  padding: 5px 12px;
  border-radius: 20px;
  text-decoration: none;
}
.event-detail-community-link:hover {
  background: #d4ebd6;
}
/* ── 6. Record & evidence ── */
.event-detail-evidence {
  background: white;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px 22px;
  font-size: 14px;
}
.event-detail-evidence summary {
  font-weight: 700;
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: space-between;
}
.event-detail-evidence summary::before {
  content: "▶";
  font-size: 11px;
  color: var(--muted);
  transition: transform 0.15s;
  flex: none;
}
.event-detail-evidence[open] summary::before {
  transform: rotate(90deg);
}
.ed-evidence-checked {
  font-size: 13px;
  font-weight: 400;
  color: var(--muted);
  margin-left: auto;
}
/* ── 7. You might also like ── */
.ed-related-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.ed-related-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
  background: none;
  border-left: none;
  border-right: none;
  border-top: none;
  border-radius: 0;
  text-align: left;
  width: 100%;
  cursor: pointer;
  transition: background 0.1s;
}
.ed-related-item:last-child {
  border-bottom: none;
}
.ed-related-item:hover {
  background: var(--mint);
}
.ed-related-poster.poster {
  width: 150px;
  height: 84px;
  border-radius: 10px;
  flex: none;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  padding: 8px 10px;
}
.ed-related-poster::after {
  display: none;
}
.ed-related-poster.poster b {
  max-width: none;
  font-size: 16px;
  font-weight: 800;
  line-height: 1;
}
.ed-related-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.ed-related-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--green-dark);
  line-height: 1.25;
}
.ed-related-when,
