#toast {
  position: fixed;
  bottom: 25px;
  left: calc(50% + 100px);
  transform: translateX(-50%) translateY(20px);
  opacity: 0;
  pointer-events: none;
  z-index: 100;
  background: var(--green-dark);
  color: white;
  border-radius: 9px;
  padding: 13px 22px;
  box-shadow: var(--shadow);
  font-size: 13px;
  transition:
    opacity 0.2s,
    transform 0.2s;
  max-width: calc(100% - 32px);
}
#toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
  pointer-events: auto;
}
#toast {
  display: flex;
  align-items: center;
  gap: 16px;
}
.toast-actions {
  display: flex;
  gap: 4px;
  flex: none;
}
.toast-actions button {
  background: transparent;
  border: 0;
  color: var(--mint);
  font: inherit;
  font-weight: 700;
  padding: 6px 8px;
  border-radius: 6px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.toast-actions button:hover {
  background: #ffffff1f;
}
.toast-actions button:focus-visible {
  outline: 2px solid var(--mint);
  outline-offset: 1px;
}
.page-enter {
  animation: reveal 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes reveal {
  from {
    opacity: 0.6;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
