  outline-offset: 2px;
}
.poster.news-art {
  height: auto;
  min-height: 170px;
  padding: 20px;
}
.poster.news-art small {
  font-size: 11px;
  letter-spacing: 1px;
  text-transform: uppercase;
}
.poster.news-art b {
  font-size: 27px;
  max-width: none;
}
.news-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 20px 24px;
  min-width: 0;
}
.news-title {
  font-size: 19px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -0.3px;
  margin-bottom: 4px;
}
.news-date {
  font-size: 15px;
}
.news-by {
  font-size: 15px;
  font-style: italic;
  color: var(--muted);
}
.news-summary {
  font-size: 15px;
  line-height: 1.6;
  margin-top: 10px;
}
.news-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  color: var(--green);
  font-size: 14px;
  font-weight: 650;
}
.news-card:hover .news-link {
  text-decoration: underline;
