  assert.equal(result, 9 * 60 + 15);
  const result2 = clampEnd(22 * 60, 9 * 60, 21, 15); // beyond gridEnd
  assert.equal(result2, 21 * 60);
});

test("blockDropAllowed: allows Mon-Fri, rejects Sat-Sun", () => {
