if (tueTueMorning) {
  test("planner: personal event on Tue 3-4 PM blocks a conflicting campus event", () => {
    const personalEvent = makePE({
      date: TUE,
      start: 15 * 60,
      end: 16 * 60,
      repeat: "none",
    });
    const state = {
      ...fresh(),
      personalEvents: [personalEvent],
      plan: [],
      cancelled: [],
