test("pixelToMins: 50% of grid = midpoint", () => {
  // Grid 8:00-21:00 (780 min span), 50% → 8*60 + 390 = 870 → snap(870/15)*15 = 870
  const result = pixelToMins(500, 1000, 8, 21);
