/* ── Personal events (student-created items) ────────────────────────────── */
:root {
  --personal: #1a6fb8;
  --personal-bg: #dceeff;
  --personal-light: #f0f7ff;
}
.dot.dot-personal {
  background: var(--personal);
}
/* Personal event blocks in Day/Week time grid */
.gcal-personal {
  background: var(--personal-bg);
  color: var(--personal);
  border-left: 3px solid var(--personal);
  cursor: grab;
}
.gcal-personal:hover {
  background: #c9e5ff;
}
.gcal-class {
  cursor: grab;
}
/* Dragging state */
.gcal-dragging {
  opacity: 0.55;
  pointer-events: none;
}
/* Resize handle at the bottom edge of own blocks */
.gcal-resize-handle {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 6px;
  cursor: ns-resize;
  border-radius: 0 0 5px 5px;
}
.gcal-resize-handle:hover {
  background: rgba(0, 0, 0, 0.12);
}
/* Personal event month chips */
.gcal-chip-personal {
  background: var(--personal-bg);
  color: var(--personal);
  box-shadow: inset 2px 0 0 var(--personal);
}
@media (max-width: 480px) {
  button.gcal-month-chip.gcal-chip-personal {
    background: var(--personal);
    box-shadow: none;
  }
}
/* + New event toolbar button */
.gcal-new-event-btn {
  margin-right: 8px;
}
/* Undo bar shown after a drag */
.gcal-undo-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  background: var(--ink);
  color: white;
  border-radius: 8px;
  font-size: 13px;
  margin-bottom: 10px;
}
.gcal-undo-bar .btn {
  background: rgba(255,255,255,0.15);
  border-color: rgba(255,255,255,0.3);
  color: white;
  font-size: 12px;
}
.gcal-undo-bar .btn:hover {
  background: rgba(255,255,255,0.25);
}
.gcal-undo-dismiss {
  margin-left: auto;
  background: none;
  border: 0;
  color: rgba(255,255,255,0.7);
  font-size: 18px;
  line-height: 1;
  padding: 0 4px;
}

/* ── PersonalEventDialog ────────────────────────────────────────────────── */
.pe-dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(21, 41, 31, 0.38);
  z-index: 300;
}
.pe-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 301;
  background: white;
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: var(--shadow);
  width: min(480px, 96vw);
