}
.news-summary {
  font-size: 15px;
  line-height: 1.6;
  margin-top: 10px;
}
.news-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  color: var(--green);
  font-size: 14px;
  font-weight: 650;
}
.news-card:hover .news-link {
  text-decoration: underline;
}
.news-link .icon {
  width: 16px;
  height: 16px;
}
.news-more {
