}
@media (max-width: 700px) {
  .news-card {
    grid-template-columns: 1fr;
  }
  .poster.news-art {
    min-height: 110px;
  }
  .news-body {
    padding: 16px 18px;
  }
  .news-title {
    font-size: 17px;
  }
