  iso: string,
  state: Pick<DemoState, "blocks" | "plan" | "cancelled"> & { personalEvents?: DemoState["personalEvents"] },
  events: readonly CampusEvent[],
  original: readonly CampusEvent[],
  includeClasses: boolean,
