  function handleDelete(id: string, kind: "personal" | "block") {
    if (kind === "block") {
      onUpdate((s) => ({ ...s, blocks: s.blocks.filter((x) => x.id !== id) }));
      notify("Busy time deleted.");
    } else {
      onUpdate((s) => ({
        ...s,
        personalEvents: (s.personalEvents ?? []).filter((x) => x.id !== id),
      }));
      notify("Event deleted.");
    }
