        setDragState(null);
        dragRef.current = null;
        return;
      }
      onUpdate((s) => ({
        ...s,
        blocks: s.blocks.map((b) =>
          b.id === ds.id ? { ...b, day: newDay, start: newStart, end: newEnd } : b,
        ),
      }));
    } else {
      // personal event
      onUpdate((s) => ({
        ...s,
        personalEvents: (s.personalEvents ?? []).map((pe) => {
          if (pe.id !== ds.id) return pe;
