      `Moved ${label} to ${dayLabel}, ${formatTimeRange(newStart, newEnd)}. Undo`,
    );

    // Store undo
    setUndoState({
      label,
      restore: (s) => ({
        ...s,
        blocks: prevBlocks,
        personalEvents: prevPersonal,
      }),
    });

    setDragState(null);
    dragRef.current = null;
  }

