              title={lbl}
              tabIndex={0}
              onPointerDown={(e) => {
                e.preventDefault(); // Fix 5: prevent text selection
                e.stopPropagation();
                onDragStart(e, item.id, "personal", "move", iso, item.start, item.end);
              }}
              onClick={(e) => {
                e.stopPropagation();
                // onEditPersonal is only called when endDrag detects no real drag
