                    <span className="gcal-tag-label">Time changed</span>
                  </em>
                ) : null}
              </span>
            ) : null}
          </button>
        );
      })}

      {showNow && DEMO_NOW_MINUTE >= grid.start * 60 && DEMO_NOW_MINUTE <= grid.end * 60 ? (
        <div className="gcal-now-line" style={{ top: `${nowPct}%` }} aria-hidden="true" />
      ) : null}
    </div>
  );
}

