            dragState={dragState}
            onDragStart={startDrag}
            onDragMove={moveDrag}
            onDragEnd={endDrag}
          />
        </div>
      ) : null}

      {view === "month" ? (
        <div className="gcal-body panel">
          {!showingDemoWeek ? <DemoWeekBanner onGoToDemo={goToDemoWeek} /> : null}
          <MonthView
            anchor={monthStart(anchor)}
            state={state}
            events={events}
            today={today}
            statuses={statuses}
            onDayClick={openDay}
            onDetail={onDetail}
            onEditPersonal={openEditPersonal}
            onCreateAt={openCreateDialog}
          />
        </div>
      ) : null}

      {view === "year" ? (
        <div className="gcal-body panel">
          {!showingDemoWeek ? <DemoWeekBanner onGoToDemo={goToDemoWeek} /> : null}
          <YearView anchor={anchor} state={state} today={today} onDayClick={openDay} />
        </div>
      ) : null}

      {/* Dialog */}
      {dialogMode ? (
        <PersonalEventDialog
          item={dialogItem}
          block={dialogBlock}
          defaultDate={dialogDefaultDate}
          defaultStart={dialogDefaultStart}
          onSave={handleSave}
          onDelete={handleDelete}
          onClose={() => setDialogMode(null)}
        />
      ) : null}
    </div>
  );
}

