  onDragEnd,
}: {
  dates: string[];
  state: DemoState;
  events: CampusEvent[];
  grid: { start: number; end: number };
  today: string | null;
  statuses: Map<string, ItemStatus>;
  onDetail: (id: string) => void;
  onDay: (dayIndex: number) => void;
  onEditPersonal: (id: string) => void;
