                <span className={`gcal-dom ${isToday ? "gcal-today-dot" : ""}`}>{dayOfMonth(iso)}</span>
                {showAdd ? (
                  <button
                    className="gcal-add-header-btn"
                    aria-label={`Find an event on ${DAY_NAMES_FULL[wdi]}`}
