  border-radius: 12px;
  padding: 14px;
}
.chat-event h3 {
  font-size: 16px;
  margin: 8px 0;
  line-height: 1.4;
}
.chat-event .meta {
  margin: 5px 0;
}
.chat-event .row {
  margin-top: 12px;
  flex-wrap: wrap;
}
