/* ── Forum layout ─────────────────────────────────────────────────────────── */
.forum-layout {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  gap: 20px;
  align-items: start;
}
.forum-sidebar {
  position: sticky;
  top: calc(var(--topbar-h) + 20px);
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 4px 0;
}
.forum-sidebar-heading {
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 14px;
  color: var(--ink);
}
.forum-community-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.forum-community-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  background: none;
  border: none;
  border-radius: 8px;
  padding: 8px 10px;
  text-align: left;
  cursor: pointer;
  transition: background 0.1s;
}
.forum-community-item:hover {
  background: var(--bg);
}
.forum-community-item.active {
  background: var(--mint);
  color: var(--green-dark);
}
.forum-community-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--green);
  color: white;
  font-size: 14px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
}
.forum-community-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}
.forum-community-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.forum-community-cat {
  font-size: 12px;
  color: var(--muted);
}
.forum-joined-badge {
  font-size: 11px;
  background: var(--green);
  color: white;
  border-radius: 4px;
  padding: 2px 6px;
  flex: none;
}

/* Feed */
.forum-feed {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.forum-feed-header {
  display: flex;
  align-items: center;
  gap: 16px;
}
.forum-feed-title {
  font-size: 19px;
  font-weight: 700;
  margin: 0;
  white-space: nowrap;
}
.forum-search-field {
  flex: 1;
  font-size: 13px;
  color: var(--muted);
  gap: 0;
}
.forum-search-field input {
  width: 100%;
}

/* New post composer */
.forum-new-post {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 0 16px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 4px;
}
.forum-new-post-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.forum-create-trigger {
  flex: 1;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--bg);
  padding: 9px 16px;
  color: var(--muted);
  text-align: left;
  font-size: 14px;
  transition: background 0.15s, border-color 0.15s;
}
.forum-create-trigger:hover {
  background: var(--mint);
  border-color: var(--green);
  color: var(--green-dark);
}

/* Post card */
.forum-post-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px 0;
  border-bottom: 1px solid var(--line);
}
.forum-post-card:last-child {
  border-bottom: none;
}
.forum-post-card-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
}
.forum-post-community {
  font-weight: 700;
  font-size: 12px;
  color: var(--green-dark);
  background: var(--mint);
  padding: 2px 8px;
  border-radius: 4px;
}
.forum-post-author {
  color: var(--muted);
  font-size: 12px;
}
.forum-post-time {
  color: var(--muted);
  font-size: 12px;
}
.forum-post-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--ink);
  text-align: left;
  white-space: normal;
  line-height: 1.35;
}
.forum-post-title:hover {
  color: var(--green);
}
.forum-post-preview {
  font-size: 14px;
  color: var(--muted);
  margin: 2px 0 0;
  line-height: 1.5;
}
.forum-post-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 6px;
}
.forum-stat {
  font-size: 13px;
  color: var(--muted);
  font-weight: 600;
  background: none;
  border: none;
  padding: 0;
}
.forum-stat.text-btn {
  cursor: pointer;
}
.forum-stat.text-btn:hover {
  color: var(--green);
}
.forum-like-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 13px;
  font-weight: 700;
  color: var(--muted);
  background: none;
  border: 1px solid transparent;
  border-radius: 20px;
  padding: 3px 10px;
  cursor: pointer;
  transition: color 0.15s, background 0.15s, border-color 0.15s;
}
.forum-like-btn:hover {
  color: var(--green);
  background: var(--mint);
  border-color: var(--green);
}
.forum-like-btn.liked {
  color: var(--green-dark);
  background: var(--mint);
  border-color: var(--green);
}
.forum-comment-like {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  background: none;
  border: none;
  padding: 2px 0;
  margin-top: 4px;
  cursor: pointer;
  transition: color 0.15s;
}
.forum-comment-like:hover {
  color: var(--green);
}
.forum-comment-like.liked {
  color: var(--green-dark);
}
.forum-empty {
  color: var(--muted);
  font-size: 14px;
  padding: 24px 0;
  text-align: center;
}

/* Post detail sub-page */
.forum-detail-page {
  display: flex;
