              <div key={h} className="gcal-hour-label">
                {time(h * 60)}
              </div>
            ))}
          </div>
          <div className="gcal-grid-lines" aria-hidden="true">
            {hours.map((h) => (
              <div key={h} className="gcal-grid-line" />
            ))}
          </div>
          {dates.map((iso) => (
            <DayColumn
