    personalEvents: [makePE({ date: TUE, start: 14 * 60, end: 15 * 60, repeat: "none" })],
  };
  const result = busyBlocks(state);
  assert.equal(result.length, 2);
});

test("busyBlocks: capped at 100", () => {
  const blocks = Array.from({ length: 80 }, (_, i) => ({
    id: `b${i}`,
