  }));
  const personalEvents = Array.from({ length: 50 }, (_, i) =>
    makePE({ id: `pe${i}` }),
  );
  const state = { blocks, personalEvents };
  const result = busyBlocks(state);
  assert.equal(result.length, 100);
});

