function withStorage(json: string, fn: () => void) {
  const mock = { getItem: (_k: string) => json, setItem: () => {}, removeItem: () => {} };
  Object.defineProperty(global, "localStorage", { value: mock, configurable: true });
  try {
    fn();
  } finally {
